using System.Text.Json;
using System.Text.RegularExpressions;

namespace ResearchAgent;

/// <summary>
/// Provides simulated web search functionality for the research agent.
/// In production, replace with a real search API (Bing Search, Google Custom Search, etc.).
/// </summary>
public static partial class WebSearchTool
{
    private static readonly HttpClient s_httpClient = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" }
        }
    };

    [Description("Searches the web for the given query and returns a list of result snippets. Use this to find information about a topic.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-5)")] int maxResults = 3)
    {
        maxResults = Math.Clamp(maxResults, 1, 5);

        try
        {
            // Use DuckDuckGo Lite (HTML) as a free search source
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";

            var response = await s_httpClient.GetStringAsync(url);

            var results = ParseDuckDuckGoResults(response, maxResults);

            if (results.Count == 0)
                return $"No results found for '{query}'. Try rephrasing the query.";

            return JsonSerializer.Serialize(new { query, results }, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try a different query.";
        }
    }

    [Description("Fetches the text content of a web page at the given URL. Use this to read full articles found via search.")]
    public static async Task<string> FetchPageAsync(
        [Description("The URL of the web page to fetch")] string url,
        [Description("Maximum number of characters to return")] int maxLength = 3000)
    {
        maxLength = Math.Clamp(maxLength, 500, 5000);

        try
        {
            var html = await s_httpClient.GetStringAsync(url);
            var text = StripHtml(html);

            if (text.Length > maxLength)
                text = text[..maxLength] + "\n... [truncated]";

            return text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch '{url}': {ex.Message}";
        }
    }

    private static List<object> ParseDuckDuckGoResults(string html, int maxResults)
    {
        var results = new List<object>();

        // Extract result links and snippets from DuckDuckGo Lite HTML
        var linkMatches = ResultLinkRegex().Matches(html);
        var snippetMatches = SnippetRegex().Matches(html);

        for (int i = 0; i < Math.Min(linkMatches.Count, maxResults); i++)
        {
            var link = WebUtility.HtmlDecode(linkMatches[i].Groups[1].Value);
            var title = WebUtility.HtmlDecode(StripHtml(linkMatches[i].Groups[2].Value));
            var snippet = i < snippetMatches.Count
                ? WebUtility.HtmlDecode(StripHtml(snippetMatches[i].Groups[1].Value)).Trim()
                : "";

            if (!link.StartsWith("http"))
                continue;

            results.Add(new { title, url = link, snippet });
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var text = HtmlTagRegex().Replace(html, " ");
        text = WhitespaceRegex().Replace(text, " ");
        return WebUtility.HtmlDecode(text).Trim();
    }

    [GeneratedRegex("""<a[^>]+href="([^"]*)"[^>]*class="result-link"[^>]*>(.*?)</a>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex ResultLinkRegex();

    [GeneratedRegex("""<td[^>]*class="result-snippet"[^>]*>(.*?)</td>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex HtmlTagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}
"}

{"path": "/tmp/sv-f041c5235b3644a08d29006092e894a4/ResearchAgent/ResearchService.cs", "file_text": "using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

public sealed class ResearchService(IChatClient chatClient, Notepad notepad)
{
    public async Task RunAsync(string[] args)
    {
        Console.WriteLine("╔══════════════════════════════════════════╗");
        Console.WriteLine("║       🔍 AI Research Agent               ║");
        Console.WriteLine("╚══════════════════════════════════════════╝");
        Console.WriteLine();

        // Build tools list from static web search methods and instance notepad methods
        var tools = new List<AITool>
        {
            AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
            AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
            AIFunctionFactory.Create(notepad.SaveNote),
            AIFunctionFactory.Create(notepad.GetNote),
            AIFunctionFactory.Create(notepad.ListNotes),
        };

        var agent = chatClient.AsAIAgent(
            name: "ResearchAgent",
            description: "An AI agent that researches topics by searching the web and taking notes.",
            instructions: """
                You are a research assistant. Your goal is to thoroughly research
                the topic the user asks about by following these steps:

                1. Break the topic into key subtopics or questions.
                2. Use SearchWebAsync to find relevant information for each subtopic.
                3. Use FetchPageAsync to read promising articles for deeper detail.
                4. Use SaveNote to record important findings with descriptive keys
                   (e.g., "definition", "key_statistics", "recent_developments").
                5. After gathering enough information, use ListNotes to review your notes.
                6. Provide a comprehensive summary that synthesizes all findings,
                   citing the sources you used.

                Be thorough but focused. Search multiple angles of the topic.
                Save notes as you go so you don't lose information between steps.
                """,
            tools: tools);

        // Determine the research topic
        string topic;
        if (args.Length > 0)
        {
            topic = string.Join(' ', args);
        }
        else
        {
            Console.Write("Enter a topic to research: ");
            topic = Console.ReadLine()?.Trim() ?? "artificial intelligence";
        }

        Console.WriteLine($"\n📚 Researching: {topic}\n");

        var session = await agent.CreateSessionAsync();
        var runOptions = new ChatClientAgentRunOptions(new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
        });

        // Stream the agent's response as it works
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly and provide a comprehensive summary: {topic}",
            session,
            runOptions))
        {
            if (update.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }

        Console.WriteLine("\n");

        // Display collected notes
        var allNotes = notepad.GetAllNotes();
        if (allNotes.Count > 0)
        {
            Console.WriteLine("═══════════════════════════════════════════");
            Console.WriteLine("📝 Research Notes Collected:");
            Console.WriteLine("═══════════════════════════════════════════");
            foreach (var (key, value) in allNotes)
            {
                Console.WriteLine($"\n▸ {key}:");
                Console.WriteLine($"  {value}");
            }
        }
    }
}
"}

